import pandas as pd

def clean(df):
    d = df.copy()
    for col in ['species', 'island', 'sex']:
        if col in d.columns:
            d[col] = d[col].astype('string').str.strip()
    if 'species' in d.columns:
        d['species'] = d['species'].replace({'Chinstarp': 'Chinstrap'})
    for col in ['bill_length_mm', 'bill_depth_mm', 'flipper_length_mm', 'body_mass_g', 'year']:
        if col in d.columns:
            d[col] = pd.to_numeric(d[col], errors='coerce')
    if 'flipper_length_mm' in d.columns:
        d['flipper_length_mm'] = d['flipper_length_mm'].abs()
        d.loc[~d['flipper_length_mm'].between(170, 235), 'flipper_length_mm'] = pd.NA
    if 'body_mass_g' in d.columns:
        m = d['body_mass_g']
        m = m.where(~(m > 6500), m / 1000)
        m = m.where(m.between(2500, 6500), pd.NA)
        d['body_mass_g'] = m
    if 'bill_length_mm' in d.columns:
        d.loc[~d['bill_length_mm'].between(30, 60), 'bill_length_mm'] = pd.NA
    d = d.drop_duplicates()
    return d

def answer(df):
    d = clean(df)
    d = d[d['species'].eq('Adelie')]
    d = d.dropna(subset=['island', 'bill_length_mm'])
    out = d.groupby('island', dropna=True)['bill_length_mm'].mean()
    return {str(k): float(v) for k, v in out.items()}
